"""Payment reminders: each reminder goes out at 09:00 in the tenant's time zone on its remind_on date.

schedule_reminder() is called when an invoice is finalized and stores the UTC send time.
"""
from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

SEND_AT = time(9, 0)


def send_time_utc(remind_on: date, tz: str, now: datetime | None = None) -> datetime:
    """UTC instant for 09:00 local on remind_on, using the offset in force on that date (not today's)."""
    return datetime.combine(remind_on, SEND_AT, tzinfo=ZoneInfo(tz)).astimezone(timezone.utc)


def schedule_reminder(invoice_id: str, due: date, tz: str, now: datetime, days_before: int = 3) -> dict:
    remind_on = due - timedelta(days=days_before)
    return {"invoice_id": invoice_id, "remind_on": remind_on.isoformat(),
            "send_at_utc": send_time_utc(remind_on, tz, now).isoformat()}

"""Invoice totals for the PDF and the API: line amounts, the discount and the total (BIL-1471)."""


def line_amount(quantity: float, unit_price: float) -> float:
    return round(quantity * unit_price, 2)


def invoice_totals(lines: list[dict], discount_pct: float = 0) -> dict:
    subtotal = sum(line_amount(l["quantity"], l["unit_price"]) for l in lines)
    discount = round(subtotal * discount_pct / 100, 2)
    return {"subtotal": subtotal, "discount": discount, "total": round(subtotal - discount, 2)}

import unittest

from billing.totals import invoice_totals, line_amount


class TestTotals(unittest.TestCase):
    def test_line_amount(self):
        self.assertEqual(line_amount(2, 49.99), 99.98)

    def test_totals_with_discount(self):
        lines = [{"quantity": 1, "unit_price": 120.00}, {"quantity": 3, "unit_price": 10.00}]
        self.assertEqual(invoice_totals(lines, discount_pct=10),
                         {"subtotal": 150.00, "discount": 15.00, "total": 135.00})


if __name__ == "__main__":
    unittest.main()

"""Webhook retry policy (BIL-1480): which delivery results are retried, and after how long."""
import random

BASE_S = 30              # first retry within 30 s, doubling each attempt
CAP_S = 6 * 3600         # never wait more than 6 hours
MAX_ATTEMPTS = 8


def should_retry(status: int | None, attempt: int) -> bool:
    """status is None when there was no response (timeout, connection error)."""
    if attempt >= MAX_ATTEMPTS:
        return False
    return status is None or status >= 400


def next_delay(attempt: int, rng: random.Random = random) -> float:
    """Full jitter: uniform between 0 and the capped exponential backoff."""
    return rng.uniform(0, min(CAP_S, BASE_S * 2 ** attempt))

import random
import unittest

from billing.retry import CAP_S, MAX_ATTEMPTS, next_delay, should_retry


class TestRetry(unittest.TestCase):
    def test_retries_server_errors_and_timeouts(self):
        self.assertTrue(should_retry(500, 1))
        self.assertTrue(should_retry(None, 1))

    def test_no_retry_on_success(self):
        self.assertFalse(should_retry(200, 1))

    def test_gives_up_after_max_attempts(self):
        self.assertFalse(should_retry(503, MAX_ATTEMPTS))

    def test_delay_is_capped(self):
        rng = random.Random(7)
        self.assertTrue(all(0 <= next_delay(a, rng) <= CAP_S for a in range(1, 20)))


if __name__ == "__main__":
    unittest.main()

import hashlib
import hmac
import json
import unittest

from billing.signing import signature_header


class TestSigning(unittest.TestCase):
    def test_header_format_and_mac(self):
        payload = {"type": "invoice.finalized", "id": "evt_1", "data": {"invoice": "in_42"}}
        body = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        mac = hmac.new(b"whsec_test", f"1762300000.{body}".encode(), hashlib.sha256).hexdigest()
        self.assertEqual(signature_header("whsec_test", payload, 1762300000), f"t=1762300000,v1={mac}")


if __name__ == "__main__":
    unittest.main()
